mapper.select:
select sdl1.ITEM_CODE id,sdl1.ITEM_VALUE text from SYS_DATADICT_LIST sdl1
inner join SYS_DATADICT_LIST_LINK sdll on sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl1.ITEM_CODE=sdll.ITEM_CODE

    and TRIM(sdll.LINKED_ITEM_CODE) = #{item_code_child}



        sdl1.ITEM_VALUE like concat(concat('%', #{search,jdbcType=VARCHAR}),'%')

SELECT TEMP.CUSTOMER_ID, TEMP.CUSTOMER_NAME, TEMP.PARTY_TYPE3, TEMP.PARTY_TYPE2, TEMP.PARTY_TYPE1, TEMP.INDUSTRY, TEMP.INDUSTRY2, TEMP.INSITITUTE_CODE, TEMP.IS_GOV, TEMP.MAIN_CAPITAL, TEMP.REGISTER_CAPITAL, TEMP.PROVINCE, TEMP.CITY, TEMP.COUNTY, TEMP.HOLDING_TYPE, TEMP.CUSTOMER_OBJ_TYPE, TEMP.IS_LISTED_COMPANY, TEMP.IS_GROUP_CUSTOMER, TEMP.PARENT_CUSTOMER_ID, TEMP.PARENT_CUSTOMER_NAME, TEMP.IS_PRIVATE, TEMP.IS_ESCAPE_DEPT, TEMP.CREDIT_TYPE, TEMP.IS_CREDIT_RELATED_TRD, TEMP.STRUCT_ADJUST_TYPE, TEMP.INDUS_UPGRATE_TYPE, TEMP.BUSI_SCOPE, TEMP.MAIN_BUSI, TEMP.SEX, TEMP.PERSON_ID, TEMP.M_PHONE, TEMP.PHONE, TEMP.POSITION, TEMP.COMPANY_NAME, TEMP.ADDRESS, TEMP.MAIL, TEMP.PROPERTY, TEMP.LINK_ID1, TEMP.LINK_ID2, TEMP.LINK_ID3, TEMP.REMARK, TEMP.CREATE_USER, TEMP.CREATE_DEPT, TEMP.CREATE_TIME, TEMP.UPDATE_USER, TEMP.UPDATE_TIME FROM ( select T1.CUSTOMER_ID, T1.CUSTOMER_NAME, T2.PARTY_TYPE3, T2.PARTY_TYPE2, T2.PARTY_TYPE1, T2.INDUSTRY, T2.INDUSTRY2, T2.INSITITUTE_CODE, T2.IS_GOV, T2.MAIN_CAPITAL, T2.REGISTER_CAPITAL, T2.PROVINCE, T2.CITY, T2.COUNTY, T2.HOLDING_TYPE, T2.CUSTOMER_OBJ_TYPE, T2.IS_LISTED_COMPANY, T2.IS_GROUP_CUSTOMER, T2.PARENT_CUSTOMER_ID, T2.PARENT_CUSTOMER_NAME, T2.IS_PRIVATE, T2.IS_ESCAPE_DEPT, T2.CREDIT_TYPE, T2.IS_CREDIT_RELATED_TRD, T2.STRUCT_ADJUST_TYPE, T2.INDUS_UPGRATE_TYPE, T2.BUSI_SCOPE, MAIN_BUSI, T2.SEX, T2.PERSON_ID, T2.M_PHONE, T2.PHONE, T2.POSITION, T2.COMPANY_NAME, T2.ADDRESS, T2.MAIL, T2.PROPERTY, T2.LINK_ID1, T2.LINK_ID2, T2.LINK_ID3, T2.REMARK, T2.CREATE_USER, T2.CREATE_DEPT, T2.CREATE_TIME, T2.UPDATE_USER, T2.UPDATE_TIME from MST_CUSTOMER_INFO T1 left join MST_CUSTOMER_INFO_ADD T2 on T1.CUSTOMER_ID = T2.CUSTOMER_ID UNION select T1.CUSTOMER_ID, T1.CUSTOMER_NAME, T2.PARTY_TYPE3, T2.PARTY_TYPE2, T2.PARTY_TYPE1, T2.INDUSTRY, T2.INDUSTRY2, T2.INSITITUTE_CODE, T2.IS_GOV, T2.MAIN_CAPITAL, T2.REGISTER_CAPITAL, T2.PROVINCE, T2.CITY, T2.COUNTY, T2.HOLDING_TYPE, T2.CUSTOMER_OBJ_TYPE, T2.IS_LISTED_COMPANY, T2.IS_GROUP_CUSTOMER, T2.PARENT_CUSTOMER_ID, T2.PARENT_CUSTOMER_NAME, T2.IS_PRIVATE, T2.IS_ESCAPE_DEPT, T2.CREDIT_TYPE, T2.IS_CREDIT_RELATED_TRD, T2.STRUCT_ADJUST_TYPE, T2.INDUS_UPGRATE_TYPE, T2.BUSI_SCOPE, MAIN_BUSI, T2.SEX, T2.PERSON_ID, T2.M_PHONE, T2.PHONE, T2.POSITION, T2.COMPANY_NAME, T2.ADDRESS, T2.MAIL, T2.PROPERTY, T2.LINK_ID1, T2.LINK_ID2, T2.LINK_ID3, T2.REMARK, T2.CREATE_USER, T2.CREATE_DEPT, T2.CREATE_TIME, T2.UPDATE_USER, T2.UPDATE_TIME from MST_CUSTOMER_INFO T1 right join MST_CUSTOMER_INFO_ADD T2 on T1.CUSTOMER_ID = T2.CUSTOMER_ID ) TEMP
#{dto.customerId}
order by TEMP.CUSTOMER_ID desc
